using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

// Web defaults include the default reflection-based resolver,
// so metadata for any serialisable type is available.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  →  Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// Options with a source-gen context that only knows about Person.
var limited = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (limited.TryGetTypeInfo<Person>(out var found))
    Console.WriteLine($"\nTryGet Person  →  resolved ({found!.Type.Name})");
else
    Console.WriteLine("\nTryGet Person  →  not available");

// Order is NOT in the source-gen context, so this should return false.
if (limited.TryGetTypeInfo<Order>(out var notFound))
    Console.WriteLine($"TryGet Order   →  resolved ({notFound!.Type.Name})");
else
    Console.WriteLine("TryGet Order   →  not available (expected)");

// --- types ---

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// Source-gen context that only handles Person
[JsonSerializable(typeof(Person))]
public partial class SmallContext : JsonSerializerContext;

